clean_output:
:param preconditions: preconditions collected from the current class
    :param func: function to process
    :return: collapsed preconditions
    """
    if bases_have_func:
        return _collapse_preconditions_with_bases(base_preconditions, preconditions)
    else:
        return _collapse_preconditions_without_bases(preconditions, func)

raw_output:
:param preconditions: preconditions collected from the current class
    :param func: function to process
    :return: collapsed preconditions
    """
    if bases_have_func:
        return _collapse_preconditions_with_bases(base_preconditions, preconditions)
    else:
        return _collapse_preconditions_without_bases(preconditions, func)


def _collapse_preconditions_with_bases(base_preconditions: List[List[Contract]],
                                       preconditions: List[List[Contract]]) -> List[List[Contract]]:
    """
    Collapse preconditions when at least one of the base classes has the function.

    :param base_preconditions: preconditions collected from the base classes (grouped by base class)
    :param preconditions: preconditions collected from the current class
    :return: collapsed preconditions
    """
    if base_preconditions:
        base_preconditions = _collapse_preconditions(base_preconditions)
    if preconditions:
        preconditions = _collapse_preconditions(preconditions)
    if base_preconditions and preconditions:
        return [base_preconditions + preconditions]
    elif base_preconditions:
        return base_preconditions
    elif preconditions:
        return preconditions
    else:
        return []


def _collapse_preconditions_without_bases(preconditions: List[List[Contract]], func: Callable[..., Any]) -> List[List[Contract]]:
    """
    Collapse preconditions when none of the base classes has the function.

    :param preconditions: preconditions collected from the current class
    :param func: function to process
    :return: collapsed preconditions
    """
    if preconditions:
        preconditions = _collapse_preconditions(preconditions)
    else:
        preconditions = []
    if preconditions:
        return [preconditions]
    elif func.__doc__:
        return []
    else:
        return [
